mapper.select:
SELECT ps.space_id AS spaceId, ps.community_id AS communityId, ps.space_no AS spaceNo, ps.space_area AS spaceArea, ps.space_type AS spaceType, ps.use_status AS useStatus, ps.owner_id AS ownerId, ps.vehicle_id AS vehicleId, ps.start_date AS startDate, ps.end_date AS endDate, ps.monthly_fee AS monthlyFee, ps.create_by AS createBy, ps.create_time AS createTime, ps.update_by AS updateBy, ps.update_time AS updateTime, ps.remark AS remark, c.community_name AS communityName, o.owner_real_name AS ownerName, o.owner_phone_number AS ownerPhoneNumber, v.plate_no AS plateNo FROM community_parking_space ps LEFT JOIN community c ON c.community_id = ps.community_id LEFT JOIN owner o ON o.owner_id = ps.owner_id LEFT JOIN community_vehicle v ON v.vehicle_id = ps.vehicle_id
AND ps.community_id = #{q.communityId}
AND ps.space_no LIKE CONCAT('%', #{q.spaceNo}, '%')
AND ps.space_area LIKE CONCAT('%', #{q.spaceArea}, '%')
AND ps.space_type = #{q.spaceType}
AND ps.use_status = #{q.useStatus}
AND ps.owner_id = #{q.ownerId}
AND ps.vehicle_id = #{q.vehicleId}
ORDER BY ps.create_time DESC, ps.space_id DESC
